#!/usr/bin/env bash
# Regenerates .github/workflows/review.yml with ai_review.py embedded (single source of truth).
set -euo pipefail; cd "$(dirname "$0")"
OUT="${OUT:-.github/workflows/review.yml}"
{ cat <<'HDR'
# jukasdrj/ai-review  .github/workflows/review.yml  (reusable; GENERATED by build.sh from ai_review.py)
# Called from each repo's .github/workflows/ai-review.yml. No third-party actions, no checkout of PR code.
name: ai-review (reusable)
on:
  workflow_call:
    inputs:
      fail_on:      { type: string, default: "STOP" }               # "STOP" or "STOP,REVISE"
      models:       { type: string, default: "glm-5.3,mistral-large-4" }  # primary,fallback
      second_model: { type: string, default: "mistral-large-4" }    # high-risk paths only; "" = off
      think:        { type: string, default: "low" }
      max_chars:    { type: number, default: 120000 }
      fork_policy:  { type: string, default: "fail" }                # fork PRs: "fail" or "pass"
    secrets:
      OLLAMA_API_KEY: { required: false }
permissions: {}
jobs:
  review:
    if: github.repository_owner == 'jukasdrj'   # foreign callers get a skipped no-op
    runs-on: ubuntu-24.04
    timeout-minutes: 15
    permissions:
      contents: read
      pull-requests: write
    steps:
      - name: AI review (Ollama Cloud)
        env:
          OLLAMA_API_KEY: ${{ secrets.OLLAMA_API_KEY }}
          GH_TOKEN: ${{ github.token }}
          REPO: ${{ github.repository }}
          PR_NUMBER: ${{ github.event.pull_request.number }}
          AI_FAIL_ON: ${{ inputs.fail_on }}
          AI_MODELS: ${{ inputs.models }}
          AI_SECOND_MODEL: ${{ inputs.second_model }}
          AI_THINK: ${{ inputs.think }}
          AI_MAX_CHARS: ${{ inputs.max_chars }}
          AI_FORK_POLICY: ${{ inputs.fork_policy }}
          AI_DEADLINE_S: "600"
        run: |
          cat > "$RUNNER_TEMP/ai_review.py" <<'AI_REVIEW_PY_EOF'
HDR
  sed 's/^/          /' ai_review.py
  cat <<'FTR'
          AI_REVIEW_PY_EOF
          python3 "$RUNNER_TEMP/ai_review.py"
FTR
} > "${OUT}.tmp" && mv "${OUT}.tmp" "$OUT"
echo "wrote $OUT"
